package com.oms.order.service;

import com.oms.common.api.OrderGoodsClient;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;

/** Bounded read models for exchange workbench; no platform writes or stock commands. */
@Service public class ExchangeWorkspace {
    @Resource private OrderRepository repository;
    @Resource private OrderCatalog catalog;
    @Resource private OrderWarehouseClient warehouse;
    @Resource private ExchangeService exchanges;
    static final String BUCKET="CASE WHEN control_state='CONTINUE_REVIEW' THEN 'REVIEW' WHEN state IN ('COMPLETED','CANCELED','CLOSED','REJECTED') THEN 'DONE' WHEN state IN ('BLOCKED','WAIT_STOCK') OR platform_operation IN ('UNKNOWN','FAILED','STOCK_WAIT') OR FIND_IN_SET('QUANTITY_MISMATCH',problem_codes)>0 OR FIND_IN_SET('ORDER_UNMATCHED',problem_codes)>0 OR FIND_IN_SET('SPEED_EXCHANGE',problem_codes)>0 OR problem_codes<>'' AND state<>'NEEDS_REVIEW' THEN 'ISSUE' WHEN approved_version IS NULL THEN 'REVIEW' WHEN stage IN ('WAIT_RETURN','RETURN_QC') THEN 'RETURN' WHEN stage='REPLACEMENT' THEN 'SHIP' WHEN stage IN ('PLATFORM_DECISION','PLATFORM_SHIPPING') OR platform_operation<>'NONE' THEN 'PLATFORM' ELSE 'REVIEW' END";
    public Map<String,Object> list(String company,String number,Long channel,String state,String kind,String problem,String bucket,int page,int size){
        return list(company,number,channel,state,kind,problem,bucket,page,size,"");
    }
    public Map<String,Object> list(String company,String number,Long channel,String state,String kind,String problem,String bucket,int page,int size,String phase){
        require(Arrays.asList("","ALL","REVIEW","ISSUE","RETURN","SHIP","PLATFORM","DONE").contains(bucket),"待办分类无效");String where=" WHERE company_code=?";List<Object> args=new ArrayList<>();args.add(company);
        if(!number.trim().isEmpty()){require(number.trim().length()<=128,"单号过长");where+=" AND (exchange_sn=? OR dispute_id=? OR platform_tid=? OR platform_oid=?)";for(int i=0;i<4;i++)args.add(number.trim());}
        if(!phase.isEmpty()){require(Arrays.asList("DURING_SALE","AFTER_SALE","UNKNOWN").contains(phase),"换货阶段无效");where+=" AND source_phase=?";args.add(phase);}
        if(channel!=null){where+=" AND channel_id=?";args.add(channel);}if(!state.isEmpty()){where+=" AND state=?";args.add(state);}if(!kind.isEmpty()){where+=" AND source_kind=?";args.add(kind);}if(!problem.isEmpty()){where+=" AND FIND_IN_SET(?,problem_codes)>0";args.add(problem);}
        Map<String,Object> counts=new LinkedHashMap<>();long total=0;for(Map<String,Object> r:repository.db().query("SELECT "+BUCKET+" bucket,COUNT(*) qty FROM oms_exchange"+where+" GROUP BY bucket",ROW,args.toArray())){counts.put(text(r,"bucket"),r.get("qty"));total+=number(r,"qty");}counts.put("ALL",total);
        String selected=bucket.isEmpty()?"ALL":bucket;if(!"ALL".equals(selected)){where+=" AND ("+BUCKET+")=?";args.add(selected);total=number(counts,selected);}int limit=Math.min(50,size(size));args.add(limit);args.add(offset(page,limit));
        List<Map<String,Object>> rows=repository.db().query("SELECT id,exchange_sn,channel_id,source_kind,fulfillment_round,round_quantity,fulfillment_hold,control_state,fulfillment_mode,linked_exchange_id,dispute_id,platform_tid,platform_oid,platform_status,source_phase,speed_exchange,state,stage,problem_codes,problem_message,last_error,platform_operation,original_sku,target_sku,target_description,requested_quantity,platform_deadline,source_modified,control_version,order_id,order_line_id,source_shipment_line_id,approved_version,fulfillment_line_id,return_qc,return_sn,JSON_UNQUOTE(JSON_EXTRACT(return_result,'$.receipt_state')) return_receipt_state,allocation_status,allocation_quantity,create_time,"+BUCKET+" work_bucket FROM oms_exchange"+where+" ORDER BY id DESC LIMIT ? OFFSET ?",ROW,args.toArray());
        goods(company,rows);return map("rows",rows,"total",total,"counts",counts);
    }
    private void goods(String company,List<Map<String,Object>> rows){Set<String> skus=new LinkedHashSet<>();for(Map<String,Object> r:rows)for(String key:Arrays.asList("original_sku","target_sku"))if(!text(r,key).isEmpty())skus.add(text(r,key));if(skus.isEmpty())return;try{Map<String,List<Map<String,Object>>> found=catalog.goods(company,new ArrayList<>(skus));for(Map<String,Object> r:rows)for(String key:Arrays.asList("original","target")){List<Map<String,Object>> matches=found.getOrDefault(text(r,key+"_sku"),Collections.emptyList());r.put(key+"_goods",matches.size()==1?matches.get(0):Collections.emptyMap());}}catch(RuntimeException failure){for(Map<String,Object> r:rows)r.put("goods_lookup_error","商品资料暂未加载，可刷新重试");}}
    public Map<String,Object> detail(String company,long id){Map<String,Object> detail=exchanges.detail(company,id);if(detail.get("platform_exchange_id")!=null){List<Map<String,Object>> sources=repository.db().query("SELECT id,dispute_id,version,source_state,conversion_state FROM oms_platform_exchange WHERE company_code=? AND id=?",ROW,company,detail.get("platform_exchange_id"));if(!sources.isEmpty())detail.put("platform_source",sources.get(0));}goods(company,Collections.singletonList(detail));ExchangePlatformProgress.enrich(repository.db(),company,Collections.singletonList(detail));detail.put("fulfillment_rounds",ExchangeRounds.records(repository,company,id));if(detail.get("order_id")!=null){detail.put("lineage",repository.db().query("SELECT l.id line_id,l.source_line_id,l.source_shipment_line_id,l.sku_sn,l.goods_name,l.quantity,l.cancelled_quantity,l.fulfillment_round,l.exchange_id,e.exchange_sn,e.state,e.source_kind FROM oms_order_line l LEFT JOIN oms_exchange e ON e.company_code=l.company_code AND e.id=l.exchange_id WHERE l.company_code=? AND l.order_id=? AND l.platform_oid=? ORDER BY l.id LIMIT 501",ROW,company,detail.get("order_id"),detail.get("platform_oid")));}return detail;}
    public Map<String,Object> createSources(String company,long order){Map<String,Object> o=context(company,map("order_id",order));Map<String,Object> e=map("id",0,"order_id",order,"platform_oid","","original_platform_order_id",o.get("platform_order_id"));return map("sources",exchanges.returnableSources(company,e),"recipient",exchanges.recipient(company,e));}
    @SuppressWarnings("unchecked") public Map<String,Object> search(String company,Map<String,Object> input){
        Map<String,Object> context=context(company,input);Map<String,Object> found=catalog.searchGoods(company,input);List<Map<String,Object>> rows=(List<Map<String,Object>>)found.get("rows");if(rows==null)throw new IllegalArgumentException("商品查询未返回结果");require(rows.size()<=20,"商品结果超过单次上限");
        if(rows.isEmpty())return found;List<String> skus=new ArrayList<>();for(Map<String,Object> row:rows){String sku=text(row,"skuSn");skus.add(sku);boolean supported=number(row,"isFd")==0&&number(row,"isPackage")==0;row.put("selectable",supported);row.put("selection_reason",supported?"":"暂不支持福袋或套装换出，请选择普通 SKU");}
        try{Map<String,Object> p=context.get("allocation_policy")==null?new LinkedHashMap<>():ExchangeService.object(context.get("allocation_policy"));if(p==null||p.isEmpty()){List<Map<String,Object>> configs=repository.db().query("SELECT policy_json FROM oms_order_allocation_config WHERE company_code=? AND channel_id=?",ROW,company,context.get("channel_id"));require(configs.size()==1,"店铺分仓规则未配置");p=ExchangeService.object(configs.get(0).get("policy_json"));}
            p=OrderAllocationPolicy.validate(p,catalog.warehouses(company));require(number(p,"enabled")==1,"店铺分仓未启用");Map<String,Object> shop=repository.config(company,number(context,"channel_id"));Map<String,Object> stockCommand=map("channel_id",context.get("channel_id"),"skus",skus,"stores",p.get("warehouse_order"),"allow_public_stock",shop.get("allow_public_stock"),"reference",context.getOrDefault("stock_reference",""));if(context.get("stock_request")!=null)stockCommand.put("allow_public_stock",ExchangeService.object(context.get("stock_request")).get("allow_public_stock"));
            Map<String,Map<String,Object>> stock=new HashMap<>();for(Map<String,Object> s:data(warehouse.exchangeStock(company,stockCommand,SecurityConstants.INNER)))stock.put(text(s,"sku_sn"),s);for(Map<String,Object> row:rows)row.put("stock",stock.getOrDefault(text(row,"skuSn"),map("status","UNKNOWN","note","库存查询未返回本商品，请重试")));found.put("warehouse_scope",p.get("warehouse_order"));
        }catch(RuntimeException failure){found.put("stock_error",failure instanceof IllegalArgumentException?failure.getMessage():"库存暂未查询成功，请刷新核对");for(Map<String,Object> row:rows)row.put("stock",map("status","UNKNOWN","note",found.get("stock_error")));}
        return found;
    }
    private Map<String,Object> context(String company,Map<String,Object> input){if(number(input,"exchange_id")>0){Map<String,Object> e=exchanges.row(company,number(input,"exchange_id"),false);if(e.get("stock_request")!=null)e.put("stock_reference",ExchangeRounds.reference(e));return e;}
        List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_order WHERE company_code=? AND id=? AND business_type='SALE'",ROW,company,number(input,"order_id"));require(rows.size()==1,"请先选择本公司的原订单");Map<String,Object> result=rows.get(0);result.remove("allocation_policy");result.remove("stock_reference");return result;
    }
}
